INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Evaluating contradictions between representations and other audit evidence
(1, 'Written Representations', 'During the audit of Redstone Capital Partners for the year ended December 31, 2025, the engagement team at Fielding & Associates discovers that management''s written representation about the completeness of related party transactions contradicts evidence obtained through independent confirmation responses. The auditor has already attempted to resolve the inconsistency through further inquiry and additional procedures. Under AU-C 580, the auditor should:', '["Accept the written representation as conclusive because it constitutes formal management acknowledgment", "Document the inconsistency as a control deficiency but issue an unmodified opinion", "Reconsider the reliability of all other written representations and the effect on the audit opinion", "Request management to revise the representation letter to match the confirmation responses"]'::jsonb, 2, 'AU-C 580.A29 requires that when written representations are inconsistent with other audit evidence, the auditor must reconsider the reliability of all representations provided by management and evaluate the effect on the audit opinion. Unlike simply accepting the representation (A), which ignores contradictory evidence, the auditor must actively investigate. Documenting as a control deficiency alone (B) understates the severity of contradictory representations.', 'hard', 4),

-- Q2: medium / L3 — Representation about management responsibility for internal control
(1, 'Written Representations', 'Oakridge Manufacturing''s controller prepares the management representation letter for the December 31, 2025 audit conducted by Hartwell & Simmons LLP. The controller includes a statement that management is responsible for the preparation and fair presentation of the financial statements. The engagement partner notes that a second responsibility acknowledgment is missing. Under AU-C 580, the representation letter should also include management''s acknowledgment of responsibility for:', '["Detecting all instances of fraud committed by employees at any level", "The design, implementation, and maintenance of internal control relevant to financial reporting", "Ensuring the auditor has access to all third-party correspondence", "Establishing and maintaining an effective audit committee"]'::jsonb, 1, 'AU-C 580.10 requires that the representation letter include management''s acknowledgment of its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements. Unlike detecting all instances of fraud (A), which conflates management''s role with an unrealistic standard, the internal control representation is achievable and required. Ensuring auditor access to third-party correspondence (C) is not a standard required representation.', 'medium', 3),

-- Q3: easy / L1 — Purpose of written representations
(1, 'Written Representations', 'What is the primary purpose of obtaining written representations from management during an audit?', '["To provide necessary audit evidence and confirm management''s responsibility for the financial statements", "To transfer legal liability for the financial statements from the auditor to management", "To serve as a substitute for substantive testing in low-risk areas", "To satisfy the auditor''s obligation to communicate with those charged with governance"]'::jsonb, 0, 'AU-C 580.03 states that written representations are a necessary form of audit evidence that provide confirmation of management''s acknowledgment of its responsibility for the financial statements and support other audit evidence. Unlike transferring legal liability (B), management already bears that responsibility independently. They are not a substitute for substantive testing (C) — unlike standalone evidence, representations complement rather than replace other procedures.', 'easy', 1),

-- Q4: easy / L1 — Who constitutes management for signing purposes
(1, 'Written Representations', 'For purposes of AU-C 580, who are the appropriate members of management to provide written representations?', '["The internal audit director and the external legal counsel", "The engagement partner and the senior audit manager", "Any employee with access to the general ledger system", "Those with appropriate responsibilities for the financial statements and knowledge of the matters concerned"]'::jsonb, 3, 'AU-C 580.09 specifies that written representations should be requested from members of management who have appropriate responsibilities for the financial statements and knowledge of the matters concerned — typically the CEO and CFO or their equivalents. Unlike the internal audit director (A), who is not a member of senior management responsible for the financial statements, the signers must have authority over financial reporting. The engagement partner (B) is part of the audit team, not management.', 'easy', 1),

-- Q5: hard / L4 — Evaluating inconsistency between oral and written representations
(1, 'Written Representations', 'During the audit of Crescent Bay Technologies for the year ended December 31, 2025, the CFO verbally confirmed to the engagement partner at Monroe & Webb CPA that all significant contracts had been disclosed. However, when the formal representation letter is presented, the CFO inserts a qualifier stating the representations are limited to matters within the CFO''s ''direct personal knowledge.'' The engagement partner evaluates this qualifier. Under AU-C 580, the most appropriate course of action is to:', '["Accept the qualifier because it accurately reflects the CFO''s scope of responsibility", "Determine whether the qualifier reduces the representations to a level that no longer provides sufficient appropriate audit evidence", "Request that the CEO sign an additional unqualified letter to supplement the CFO''s letter", "Treat the qualified letter as equivalent to a refusal and immediately issue a disclaimer of opinion"]'::jsonb, 1, 'AU-C 580.20 requires the auditor to evaluate whether any qualifications or limitations placed on written representations reduce the evidence to a level that is no longer sufficient and appropriate. A ''direct personal knowledge'' qualifier may be acceptable if it does not undermine the substance of the representations. Unlike automatically treating any qualifier as a refusal (D), the auditor must first evaluate the qualifier''s impact. Simply accepting it without evaluation (A) would also be inappropriate.', 'hard', 4),

-- Q6: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'To whom is the management representation letter addressed under AU-C 580?', '["The entity''s board of directors or audit committee", "The Securities and Exchange Commission", "The auditor performing the engagement", "The entity''s external legal counsel"]'::jsonb, 2, 'AU-C 580.13 states that the written representation letter should be addressed to the auditor. Unlike communications with the board of directors (A), which serve governance purposes, the representation letter is a direct communication from management to the auditor who requested it. It is not submitted to the SEC (B) or legal counsel (D).', 'easy', 1),

-- Q7: medium / L2 — Representation about completeness of transactions
(1, 'Written Representations', 'Warren & Associates is completing the audit of Bridgeport Logistics Corp. for the year ended December 31, 2025. The engagement partner requests that the management representation letter include a statement about the completeness of information provided. The controller asks what this representation specifically covers. Under AU-C 580, the completeness representation confirms that management has provided the auditor with:', '["All financial information and access to all records, documentation, and personnel relevant to the audit", "A copy of every document created by the entity during the fiscal year", "Assurance that no employee has committed fraud during the period under audit", "A certified statement that all account balances have been verified by external parties"]'::jsonb, 0, 'AU-C 580.10 requires that management represent it has provided the auditor with all information relevant to the preparation and fair presentation of the financial statements, and access to all records, documentation, and other matters. Unlike providing every document ever created (B), which is impractical, this representation addresses the scope of relevant information. External verification of balances (D) confuses management representations with third-party audit procedures.', 'medium', 2),

-- Q8: easy / L1 — Classification of written representations as evidence
(1, 'Written Representations', 'In the hierarchy of audit evidence reliability, written representations from management are classified as:', '["External evidence obtained directly by the auditor", "Internal evidence that is oral in nature", "Internal evidence that is documentary in nature", "Corroborating evidence obtained from third parties"]'::jsonb, 2, 'AU-C 580 and AU-C 500 classify written representations as internal documentary evidence — they originate from the entity (internal) and are in written form (documentary). Unlike external evidence such as bank confirmations (A), representations come from the client, not a third party. While management may also provide oral representations (B), the formal representation letter is a written document, making it documentary rather than oral.', 'easy', 1),

-- Q9: easy / L2 — Representation about uncorrected misstatements
(1, 'Written Representations', 'At the conclusion of the audit of Pinnacle Distribution Inc. for the year ended December 31, 2025, the engagement team at Collins & Parker LLP identifies three immaterial misstatements totaling $42,000 that management has elected not to correct. The engagement partner includes a representation in the management letter about these items. Under AU-C 580, management''s written representation regarding uncorrected misstatements should state that:', '["The auditor has agreed that the misstatements are immaterial and no further action is needed", "All misstatements have been corrected prior to the issuance of the financial statements", "The uncorrected misstatements will be corrected in the subsequent fiscal year", "Management believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole"]'::jsonb, 3, 'AU-C 580.11 requires that the written representation letter include management''s belief that the effects of uncorrected misstatements aggregated during the audit are immaterial, both individually and in the aggregate. A summary of these items should be attached to the letter. Unlike option A, which improperly shifts the judgment to the auditor, the representation must reflect management''s own assessment. Correcting all misstatements (B) is factually incorrect when management elects not to adjust.', 'easy', 2),

-- Q10: medium / L3 — Management lacks knowledge to make a representation
(1, 'Written Representations', 'During the audit of Glenview Hospitality Group for the year ended December 31, 2025, the engagement partner at Crawford & Lee requests a representation about the completeness of environmental liabilities. The CEO responds that neither she nor the CFO possesses technical expertise to evaluate potential environmental remediation obligations. Under AU-C 580, the auditor should:', '["Accept the CEO''s oral assurance that no environmental liabilities exist in lieu of a written representation", "Waive the representation requirement for environmental liabilities since management lacks expertise", "Evaluate whether management''s inability to provide the representation raises doubt about the reliability of related representations and consider the effect on the audit", "Engage an environmental specialist and include the specialist''s conclusions in the representation letter as a substitute"]'::jsonb, 2, 'AU-C 580.A23 states that when management is unable to provide a requested representation, the auditor should discuss the matter with management and reconsider the reliability of other representations. The auditor must consider whether additional audit procedures are needed. Unlike waiving the requirement (B), the auditor cannot simply bypass a necessary representation. An oral assurance (A) does not satisfy the written representation requirement because AU-C 580 mandates written documentation.', 'medium', 3),

-- Q11: medium / L2 — Representation about access to records
(1, 'Written Representations', 'Hoffman & Prescott LLP is performing the audit of Silverline Manufacturing Corp. for the year ended December 31, 2025. The senior auditor drafts the representation letter and asks the engagement partner whether a specific representation about records access is required. Under AU-C 580, the management representation letter should include a statement confirming that management has provided the auditor with:', '["Access to board minutes only for meetings held during the audit period", "All relevant information, any additional information the auditor requested, and unrestricted access to persons within the entity", "Access to financial records but not personnel files or operational data", "Access only to records that management deems relevant to the audit scope"]'::jsonb, 1, 'AU-C 580.10 requires management to represent that it has provided the auditor with all relevant information, any additional information requested, and unrestricted access to persons within the entity from whom the auditor determines it necessary to obtain audit evidence. Limiting access to board minutes only (A) would be incomplete. Unlike management-selected records (D), AU-C 580 requires unrestricted access determined by the auditor''s needs.', 'medium', 2),

-- Q12: hard / L4 — Materiality threshold in representation letter
(1, 'Written Representations', 'The CFO of Apex Technologies Inc. proposes adding a materiality threshold to the management representation letter for the December 31, 2025 audit. Specifically, the CFO wants to limit representations to matters exceeding $500,000, arguing this aligns with the auditor''s planning materiality. The engagement partner at Davidson & Hale evaluates this proposal. Under AU-C 580, inserting a management-defined materiality threshold into the representation letter is:', '["Required, because representations should align with the materiality levels used in planning the audit", "Acceptable, provided the threshold is documented in the engagement letter and approved by the audit committee", "Appropriate only if the threshold matches the auditor''s tolerable misstatement amount for the engagement", "Generally inappropriate, because certain required representations (such as fraud and completeness) apply regardless of any materiality threshold"]'::jsonb, 3, 'AU-C 580.A13 indicates that certain representations, particularly those related to fraud, completeness of information provided, and related party transactions, apply regardless of materiality. Allowing management to insert a materiality threshold could exclude important matters from the representations. Unlike option A, the standard does not require or mandate a materiality threshold. Audit committee approval (B) does not override the requirement that fraud and completeness representations remain unrestricted.', 'hard', 4),

-- Q13: easy / L1 — Period covered by the representation letter
(1, 'Written Representations', 'The management representation letter covers representations about which time period?', '["The financial reporting period covered by the auditor''s opinion and through the date of the auditor''s report", "Only the fiscal year under audit, excluding any subsequent events", "The three-year lookback period required by generally accepted auditing standards", "The twelve months preceding the date the representation letter is signed"]'::jsonb, 0, 'AU-C 580.14 specifies that written representations cover the periods referred to in the auditor''s report — the financial reporting period under audit — and extend through the date of the auditor''s report. Unlike option B, excluding subsequent events is incorrect because the letter addresses events through the report date. There is no three-year lookback requirement (C), and the period is not based on the signing date (D) but the report date.', 'easy', 1),

-- Q14: medium / L3 — Representations about accounting estimates
(1, 'Written Representations', 'Maplewood Industries reports a $3.2 million warranty liability in its December 31, 2025 financial statements. The engagement team at Foster & Quinn LLP requests a written representation about this estimate. The controller asks what the representation should address beyond the dollar amount. Under AU-C 580, the written representation about significant accounting estimates should specifically address the:', '["Reasonableness of significant assumptions used by management in making the estimate", "Auditor''s independent recalculation of the estimate using alternative data sources", "A commitment to adjust the estimate if actual costs differ by more than five percent", "Statistical confidence interval for the estimate based on historical data"]'::jsonb, 0, 'AU-C 580.12 requires representations about whether the methods, significant assumptions, and data used in making accounting estimates are appropriate in the context of the applicable financial reporting framework. A commitment to adjust based on a fixed percentage (C) is not a valid representation — estimates are assessed at the reporting date, not retroactively. Unlike the auditor''s own recalculation (B), the representation focuses on management''s inputs.', 'medium', 3),

-- Q15: medium / L3 — Representation about compliance with laws and regulations
(1, 'Written Representations', 'During the audit of Northfield Healthcare Systems for the year ended December 31, 2025, the engagement team at Linden & Kaye CPA discovers that Northfield operates in a heavily regulated industry. The engagement partner considers whether to request an additional written representation about regulatory compliance. Under AU-C 580, the auditor should request a representation about:', '["Management''s intent to comply with future regulations that have not yet been enacted", "The entity''s competitive position relative to other healthcare providers in the region", "All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements", "A representation that the entity has never violated any law or regulation in its operating history"]'::jsonb, 2, 'AU-C 580.11 requires a representation that management has disclosed to the auditor all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements. Unlike future compliance intent (A), which is forward-looking and not a standard representation, the required representation focuses on known or suspected violations. A claim of zero historical violations (D) goes beyond what AU-C 580 requires and is unrealistic for most entities.', 'medium', 3),

-- Q16: easy / L1 — Minimum consequence of refusing a single representation
(1, 'Written Representations', 'Under AU-C 580, what is the minimum audit opinion consequence when management refuses to provide even one of the required written representations?', '["The auditor issues a qualified opinion only if the refused representation relates to a material account", "The auditor issues an unmodified opinion with an emphasis-of-matter paragraph", "The auditor adds an other-matter paragraph but does not modify the opinion", "The auditor disclaims an opinion on the financial statements"]'::jsonb, 3, 'AU-C 580.20 states that if management does not provide one or more of the requested written representations, the auditor should disclaim an opinion on the financial statements. A refusal to provide required representations is treated as a scope limitation serious enough to preclude an opinion. Unlike a qualified opinion (A), which addresses isolated scope limitations, AU-C 580 requires a full disclaimer because the refusal calls into question all management assertions.', 'easy', 1),

-- Q17: hard / L4 — Representations in a group audit
(1, 'Written Representations', 'Thornton & Associates serves as the group engagement partner for the consolidated audit of Keystone Holdings for the year ended December 31, 2025. Keystone has three significant components, each audited by different component auditors in separate jurisdictions. The group engagement partner evaluates whether to obtain written representations from component management in addition to group management. Under AU-C 600, in a group audit the group engagement partner should:', '["Obtain written representations from group management that address matters relevant to the consolidated financial statements, and request the component auditors to obtain representations from component management", "Rely exclusively on the component auditors'' work papers without obtaining separate representations from component management", "Obtain a single combined representation letter signed by all component managers and the group CFO", "Require component management to submit representations directly to the group audit committee rather than to the auditor"]'::jsonb, 0, 'AU-C 600.40 requires the group engagement partner to request group management to provide written representations and also to request component auditors to obtain representations from component management on matters relevant to the group audit. Unlike relying solely on component work papers (B), which does not satisfy the representation requirement, each component''s management provides its own letter. A single combined letter (C) is impractical across separate jurisdictions.', 'hard', 4),

-- Q18: medium / L2 — Representation about title to assets
(1, 'Written Representations', 'Prescott & Dunn LLP is completing the audit of Clearfield Equipment Leasing Corp. for the year ended December 31, 2025. The entity holds $18 million in equipment on its balance sheet. The engagement partner considers which representation about these assets to include in the management letter. Under AU-C 580, the representation about assets typically confirms that:', '["All assets have been appraised by an independent valuation expert during the current year", "The entity has satisfactory title to all assets, and there are no liens or encumbrances other than those disclosed in the financial statements", "Every asset on the balance sheet has been physically inspected by management within the last 90 days", "The carrying value of all assets equals their current fair market value"]'::jsonb, 1, 'AU-C 580.11 includes a representation that the entity has satisfactory title to assets and that any liens, encumbrances, or pledges are disclosed in the financial statements. Unlike independent appraisal (A), which is a valuation procedure rather than a representation, AU-C 580 focuses on ownership and encumbrances. Carrying value equaling fair value (D) conflates two distinct measurement concepts and is not a standard representation.', 'medium', 2),

-- Q19: medium / L2 — Representation about pledged or collateralized assets
(1, 'Written Representations', 'Harmon & Beck CPA is auditing the financial statements of Ridgeline Distributors Inc. for the year ended December 31, 2025. Ridgeline has a $6 million credit facility secured by its accounts receivable and inventory. The engagement partner requests a specific written representation about collateralized assets. Under AU-C 580, management should represent that:', '["The lender has confirmed the collateral arrangements directly to the auditor", "No adjustments to the carrying value of pledged assets are necessary under any circumstances", "All assets that have been pledged as collateral or otherwise encumbered have been properly disclosed in the financial statements", "The pledged assets have been segregated from unpledged assets in the entity''s warehouse"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that any liens, pledges, or encumbrances on assets have been disclosed in the financial statements. The focus is on complete disclosure of collateral arrangements. Unlike lender confirmation (A), which is a separate audit procedure, AU-C 580 requires management''s own assertion. Physical segregation of pledged assets (D) is an operational matter, not a financial statement disclosure requirement.', 'medium', 2),

-- Q20: easy / L1 — Difference between written representations and external confirmations
(1, 'Written Representations', 'What is the key distinction between written representations obtained under AU-C 580 and external confirmations obtained under AU-C 505?', '["Written representations come from internal sources (management), while external confirmations come from independent third parties", "Written representations are optional, while external confirmations are always mandatory", "Written representations are obtained at the beginning of the audit, while confirmations are obtained at year-end", "Written representations provide more reliable evidence than external confirmations"]'::jsonb, 0, 'AU-C 580 addresses written representations from management (an internal source), while AU-C 505 covers external confirmations from independent third parties. This source distinction affects reliability — external confirmations are generally more reliable because they come from parties outside the entity. Unlike option D, written representations are less reliable than external confirmations, not more. Written representations are not optional (B) — they are required on every audit.', 'easy', 1),

-- Q21: hard / L4 — Customizing representations for specialized industries
(1, 'Written Representations', 'Palmer & Associates is engaged to audit the financial statements of Heritage Mutual Insurance Company for the year ended December 31, 2025. Heritage maintains $45 million in loss reserves that are based on actuarial projections. The engagement partner evaluates whether the standard representation letter is sufficient or requires additional industry-specific representations. Under AU-C 580, the engagement partner should:', '["Use only the standard representation letter template without modification, as AU-C 580 prohibits entity-specific additions", "Limit the representations to those prescribed by the state insurance commissioner''s office", "Accept the actuarial report as a substitute for any written representations about loss reserves", "Include additional representations about loss reserves, such as management''s acknowledgment of the methods, assumptions, and data used in developing the actuarial estimates"]'::jsonb, 3, 'AU-C 580.12-.13 permit and may require the auditor to request additional written representations beyond the standard items, particularly when significant accounting estimates are involved. For an insurance company, representations about actuarial methods, assumptions, and data inputs for loss reserves are appropriate. Unlike option A, AU-C 580 does not prohibit entity-specific additions — it contemplates them. An actuarial report (C) supports but does not replace management''s own representations.', 'hard', 4),

-- Q22: medium / L3 — Broad "to the best of our knowledge" qualifier
(1, 'Written Representations', 'During the audit of Summit Ventures LLC for the year ended December 31, 2025, the CEO and CFO sign the management representation letter but add the phrase ''to the best of our knowledge and belief'' to every representation, including the representation about fraud. The engagement partner at Blake & Whitmore considers whether this qualifier is acceptable. Under AU-C 580, the ''to the best of our knowledge and belief'' qualifier is:', '["Never acceptable because it introduces uncertainty into every representation", "Appropriate for representations about matters for which management would not reasonably be expected to have absolute knowledge, but not for representations confirming management''s responsibility for the financial statements", "Acceptable only when the entity is privately held and not subject to SEC regulations", "Required on all representations to protect management from potential legal liability"]'::jsonb, 1, 'AU-C 580.A15 distinguishes between two types of representations: those about factual matters within management''s direct knowledge (e.g., acknowledging responsibility for the financial statements), and those involving judgment or completeness about which management would not be expected to have absolute knowledge. The qualifier ''to the best of our knowledge and belief'' is appropriate for the latter but not the former. Unlike option A, which claims it is never acceptable, the standard explicitly contemplates this qualifier for certain representations. It is not required on all representations (D).', 'medium', 3),

-- Q23: medium / L2 — Representation about going concern
(1, 'Written Representations', 'Russell & Hayes LLP is completing the audit of Beacon Technologies Corp. for the year ended December 31, 2025. During the audit, the engagement team identifies conditions that raise substantial doubt about Beacon''s ability to continue as a going concern. Management has developed plans to mitigate the going concern risk. Under AU-C 580, the engagement partner should request a written representation that:', '["Management has disclosed to the auditor all plans and intentions that may affect the carrying amounts or classification of assets and liabilities", "The auditor agrees that management''s going concern plans will be successful", "The entity has obtained written assurances from all creditors that no loans will be called", "The audit committee has independently verified management''s going concern assessment"]'::jsonb, 0, 'AU-C 580.11 requires representations that management has disclosed all information about plans and intentions that may affect the carrying amounts or classification of assets and liabilities. When going concern issues exist, this representation is especially important because management''s plans directly affect financial statement presentation. Unlike an auditor agreement that plans will succeed (B), which improperly merges auditor judgment with management assertions, the representation must come from management alone. Creditor assurances (C) are not a standard representation requirement.', 'medium', 2),

-- Q24: hard / L3 — Required vs. requested representations and impact on audit report
(1, 'Written Representations', 'The engagement partner at Griffin & Moore CPA categorizes the representations in the management letter for Westfield Industries'' December 31, 2025 audit into two groups: those explicitly required by AU-C 580 and additional representations requested based on the engagement circumstances. If management refuses to provide an additional requested representation (not one required by AU-C 580), the auditor should:', '["Automatically issue a disclaimer of opinion, as any refusal constitutes a scope limitation", "Evaluate the refusal''s implications, consider the effect on the reliability of other representations, and determine whether additional audit procedures are needed or a modified opinion is warranted", "Accept the refusal without any further action because additional representations are entirely at management''s discretion", "Withdraw from the engagement immediately because the refusal indicates management lacks integrity"]'::jsonb, 1, 'AU-C 580.20-.21 requires the auditor to evaluate the implications when management does not provide requested representations. While a refusal of required representations results in a disclaimer, a refusal of additional requested representations requires the auditor to consider the reasons and evaluate the effect on reliability. Unlike automatic disclaimer (A), which applies only to required representations, additional representations require professional judgment. Accepting without action (C) ignores the auditor''s responsibility to evaluate all refusals.', 'hard', 3),

-- Q25: medium / L2 — Representation about side agreements
(1, 'Written Representations', 'Kimball & Associates is performing the audit of Pacific Coast Development Corp. for the year ended December 31, 2025. During testing, the engagement team discovers that Pacific Coast has an informal arrangement with a major vendor involving deferred payment terms not documented in the formal purchase agreements. The engagement partner requests a written representation from management about side agreements. Under AU-C 580, the representation should confirm that:', '["All vendor invoices have been paid within the standard 30-day payment terms", "The auditor is not permitted to inquire about informal business arrangements", "Only agreements exceeding $1 million in value need to be disclosed in the representation letter", "There are no formal or informal side agreements or arrangements that have not been disclosed to the auditor"]'::jsonb, 3, 'AU-C 580.11 requires management to represent that it has provided the auditor with all information relevant to the financial statements, which includes undisclosed side agreements. The representation covers both formal contracts and informal arrangements. Unlike option C, which imposes a dollar threshold, completeness-related representations are not subject to materiality limits. Claiming the auditor cannot inquire about informal arrangements (B) contradicts the auditor''s professional responsibilities under AU-C 580.', 'medium', 2),

-- Q26: medium / L2 — Representation about litigation and claims
(1, 'Written Representations', 'During the audit of Mercer Pharmaceuticals Inc. for the year ended December 31, 2025, the engagement team at Ashford & Price LLP identifies several pending product liability lawsuits. The engagement partner requests a written representation about litigation. Under AU-C 580, the representation about litigation, claims, and assessments should confirm that management has disclosed:', '["Only those lawsuits where a loss is considered probable and the amount can be reasonably estimated", "All known actual or possible litigation, claims, and assessments whose effects should be considered when preparing the financial statements", "Only lawsuits that have been formally served with a complaint prior to the balance sheet date", "All lawsuits regardless of whether they have any financial statement impact"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that it has disclosed all known actual or possible litigation, claims, and assessments whose effects should be considered in the financial statements. Unlike option A, which applies the ASC 450 accrual threshold of probable/estimable, the representation letter requires broader disclosure. Limiting to formally served lawsuits (C) would exclude known but unserved claims that may still require financial statement consideration.', 'medium', 2),

-- Q27: medium / L2 — Representation about subsequent events in the letter
(1, 'Written Representations', 'Bradford & Simmons LLP completes the audit of Lakeview Financial Services Corp. with a report date of March 3, 2026 for the year ended December 31, 2025. The engagement partner finalizes the management representation letter and ensures it includes a representation about subsequent events. Under AU-C 580, the subsequent events representation should state that:', '["All events occurring subsequent to the date of the financial statements and through the date of the representation letter that require adjustment or disclosure have been properly accounted for", "Only events that occurred before the balance sheet date require disclosure in the representation letter", "Management has delegated responsibility for subsequent event identification to the audit committee", "The auditor has independently verified all subsequent events and management bears no responsibility for identifying them"]'::jsonb, 0, 'AU-C 580.11 requires the representation letter to include a statement that all subsequent events occurring after the balance sheet date and through the date of the auditor''s report (which is the same as the representation letter date) that require adjustment or disclosure have been properly accounted for. Unlike option B, which limits to events before the balance sheet date, the representation covers the full subsequent events window. Delegating subsequent event identification to the audit committee (C) does not relieve management of its responsibility under AU-C 580.', 'medium', 2),

-- Q28: medium / L3 — Written representations in an initial audit
(1, 'Written Representations', 'Wallace & Harper CPA is engaged to perform the initial audit of Skyline Logistics Inc. for the year ended December 31, 2025. The prior year''s financial statements were not audited. The engagement partner considers whether any additional or modified written representations are needed for an initial engagement compared to a recurring audit. Under AU-C 580 and AU-C 510, in an initial audit the auditor should:', '["Waive the representation letter requirement because there is no prior-year audit to reference", "Obtain a supplemental representation letter signed by the predecessor auditor confirming the accuracy of prior-year balances", "Obtain written representations from management that address whether the accounting policies selected and applied are appropriate, including any representations about opening balances and the consistency of accounting methods", "Limit the representation letter to cover only the current year, excluding any reference to prior-period matters or opening balances"]'::jsonb, 2, 'AU-C 510.09 and AU-C 580 require that in an initial audit, the auditor obtain representations covering opening balances and the appropriateness and consistency of accounting policies. Opening balances are particularly important because they affect the current year''s financial statements. Unlike option A, waiving the letter is never permitted — written representations are mandatory for every audit. A predecessor auditor supplemental letter (B) is not required because the predecessor does not provide representations to the successor.', 'medium', 3),

-- Q29: medium / L3 — Representations when entity uses a service organization
(1, 'Written Representations', 'Garrison & Locke LLP is auditing the financial statements of Stratton Payroll Solutions Corp. for the year ended December 31, 2025. Stratton outsources its payroll processing to a third-party service organization. The engagement partner evaluates whether additional representations are needed regarding the service organization. Under AU-C 402 and AU-C 580, the engagement partner should request a written representation from management confirming that:', '["The service organization''s SOC 1 report has been reviewed by the audit committee and no exceptions were noted", "Management has sole custody of all data processed by the service organization and can produce it on demand", "The service organization has provided its own written representation letter directly to the auditor", "Management''s description of the nature and terms of its contractual relationship with the service organization is complete and accurate, and all transactions have been properly recorded"]'::jsonb, 3, 'AU-C 402.16 and AU-C 580 require the auditor to obtain representations that management''s description of the service organization arrangement is complete and that all transactions processed by the service organization have been properly recorded. Unlike the SOC 1 report review (A), which is an audit procedure, AU-C 580 requires a management representation. The service organization does not provide its own representation letter to the user auditor (C) — the user entity''s management provides the representations.', 'medium', 3),

-- Q30: easy / L1 — Consequence of limiting representations to material matters only
(1, 'Written Representations', 'Under AU-C 580, if management insists on limiting all written representations to only those matters that exceed a specified dollar threshold, the auditor should recognize that:', '["This limitation is standard practice and requires no additional auditor action", "Certain representations, such as those about fraud and completeness, are not subject to a materiality limitation and must apply without a dollar threshold", "The auditor should accept the limitation and adjust the materiality level for the audit accordingly", "The limitation must be approved by the audit committee before the auditor can proceed"]'::jsonb, 1, 'AU-C 580.A13 notes that certain written representations apply regardless of materiality, including representations about fraud, completeness of information provided to the auditor, and related party transactions. Unlike option A, which suggests standard practice, accepting a blanket materiality limitation could exclude critical information. Audit committee approval (D) does not override the requirement that certain representations remain unrestricted by materiality thresholds.', 'easy', 1)
;

COMMIT;
